import{_ as t,o as i,c as s,a2 as e}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"插件（MCP）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plugins.md","filePath":"guide/plugins.md","lastUpdated":1788601681000}'),d={name:"guide/plugins.md"};function l(h,a,n,r,p,o){return i(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="插件-mcp" tabindex="-1">插件（MCP） <a class="header-anchor" href="#插件-mcp" aria-label="Permalink to &quot;插件（MCP）&quot;">​</a></h1><p>插件把外部工具服务器接进 Tau：通过 Model Context Protocol（MCP），任何实现该协议的工具服务器都能把它的工具注册进 Tau 的工具注册表，AI 计划即可调用。</p><h2 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">command-or-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 注册一个 MCP 服务器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # 查看已注册插件</span></span></code></pre></div><p>Tau 内置 MCP 客户端层（<code>@tau/plugins</code>），通过 stdio/HTTP 与服务器通信。插件注册的工具在目录里以插件名为前缀呈现，与内置工具共用同一套计划-审查-执行管线。</p><h2 id="安全规则-插件工具永远是-medium-risk" tabindex="-1">安全规则：插件工具永远是 medium risk <a class="header-anchor" href="#安全规则-插件工具永远是-medium-risk" aria-label="Permalink to &quot;安全规则：插件工具永远是 medium risk&quot;">​</a></h2><p>这是刻意的底线：来自外部服务器的工具，Tau 无法审查其内部实现，因此<strong>一律</strong>按 medium 风险对待——它们永远不能静默自动执行，必须经过与写入操作相同的确认门。插件扩展的是能力面，不是信任面。</p><h2 id="技能还是插件" tabindex="-1">技能还是插件？ <a class="header-anchor" href="#技能还是插件" aria-label="Permalink to &quot;技能还是插件？&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>技能</th><th>插件</th></tr></thead><tbody><tr><td>形态</td><td>一个 SKILL.md 文档</td><td>独立工具服务器进程</td></tr><tr><td>工具</td><td>声明式命令（展开成意图）</td><td>真实的可执行工具</td></tr><tr><td>风险</td><td>声明制，走审查</td><td>一律 medium</td></tr><tr><td>适合</td><td>提示注入、流程约定</td><td>真正的外部系统能力</td></tr></tbody></table><p>需要零代码注入选<a href="/Tau/guide/skills.html">技能</a>；需要接真实的系统选插件。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><p>插件不可达时 Tau 会诚实降级：该插件的工具从目录中移除并附说明，其余管线照常。<code>tau plugin list</code> 显示每个插件的可用性；网络型服务器注意检查 URL 与认证环境变量。</p>`,12)])])}const c=t(d,[["render",l]]);export{u as __pageData,c as default};
